#!/bin/bash
# KADIMA forecast milestones release (PR #48, commit 2fed0330a0d8a2b7ee0cfa62643eec552d2a2a24).
# Run on EC2 as ubuntu, after 15:45 IST, and only AFTER deploy_forecast_scoring_20261020.sh (PR #47)
# has finished with "DONE". Forecast display only: replaces kadima/hourly_forecast.py and the two
# panel files in /var/www/html (forecast.html, celestial_forecast_embed.js), and bumps the panel's
# script tag in dashboard.html to v=5. No Gamma Blast, CAS, Shield, Angel One or trading change.
#   bash deploy_forecast_milestones_20261020.sh            # gates, backup, install, restart, health
#   bash deploy_forecast_milestones_20261020.sh --rollback # restore the backups and restart
set -u
ROOT=${KADIMA_ROOT:-$HOME/kadima-py}; DATA=${KADIMA_DATA_DIR:-/var/lib/kadima}; WWW=${KADIMA_WWW:-/var/www/html}
F=$ROOT/kadima/hourly_forecast.py
PREV=f4fb1b07ce4026557ca5a121f6ab3d745e1a4c76c7e6f7cc5806450bae936cd9   # PR #47 release (must be live)
NEW=16b92751a7a1dfc024ac09fdeaa4fb7759943b587452e98912968e64022598e8    # this release
NEW_HTML=c8e88118879903e42c11fb0bcdae25d7b232e565fad58741b30d61c6b80e4f6f
NEW_JS=602713be578c2ebac167379f454cd6dff71433b89c475d3db92ed42e3d1e08dd
MARK=$ROOT/.milestones-20261020-backup
h() { sha256sum "$1" 2>/dev/null | cut -c1-64; }
health() {
  sleep 25
  systemctl is-active --quiet kadima || { echo "HEALTH FAIL: kadima not active"; return 1; }
  if journalctl -u kadima --since "-1 min" --no-pager | grep -q "Traceback"; then echo "HEALTH FAIL: traceback"; return 1; fi
  echo "health ok"; return 0
}
restore() {   # $1 = backup dir
  local BD=$1
  [ "$(h $BD/hourly_forecast.py)" = "$PREV" ] || { echo "ABORT: backup $BD/hourly_forecast.py is not the PR #47 release"; return 1; }
  cp -p "$BD/hourly_forecast.py" "$F"
  for x in forecast.html celestial_forecast_embed.js dashboard.html; do
    [ -f "$BD/www/$x" ] && sudo cp "$BD/www/$x" "$WWW/$x"
  done
  sudo systemctl restart kadima && health
  echo "restored: hourly_forecast.py $(h $F | cut -c1-12) (PR #47 f4fb1b07ce40), panel files from $BD/www"
}
if [ "${1:-}" = "--rollback" ]; then
  [ -f "$MARK" ] || { echo "ABORT: no backup marker $MARK"; exit 1; }
  restore "$(cat $MARK)"; exit
fi
echo "== 1. gates"
CUR=$(h $F); echo "live ${CUR:0:12}  needs PR #47 ${PREV:0:12}  release ${NEW:0:12}"
[ "$CUR" = "$NEW" ] && { echo "already installed"; exit 0; }
[ "$CUR" = "$PREV" ] || { echo "ABORT: PR #47 is not live (run deploy_forecast_scoring_20261020.sh first); nothing changed"; exit 1; }
HM=$(TZ=Asia/Kolkata date +%H%M); DOW=$(TZ=Asia/Kolkata date +%u)
if [ "$DOW" -le 5 ] && [ "$HM" -ge 0900 ] && [ "$HM" -lt 1545 ]; then echo "ABORT: market hours (IST $HM); run after 15:45"; exit 1; fi
for x in forecast.html celestial_forecast_embed.js dashboard.html; do
  [ -f "$WWW/$x" ] || { echo "ABORT: $WWW/$x not found (forecast panel not installed); nothing changed"; exit 1; }
done
grep -q 'celestial_forecast_embed\.js[^"]*"></script><!-- HOURLY FORECAST v1 -->' "$WWW/dashboard.html" \
  || { echo "ABORT: dashboard.html has no forecast panel tag; nothing changed"; exit 1; }
free -m | head -3
read -r -p "No open positions and OK to restart kadima now? type YES: " OK; [ "$OK" = "YES" ] || { echo "stopped, nothing changed"; exit 1; }
echo "== 2. backup"
TS=$(date +%Y%m%d_%H%M%S); BD=$HOME/backups/forecast-milestones-$TS; mkdir -p $BD/www
cp -p "$F" "$BD/" || { echo "ABORT: backup failed"; exit 1; }
for x in forecast.html celestial_forecast_embed.js dashboard.html; do cp -p "$WWW/$x" "$BD/www/$x" || { echo "ABORT: backup of $x failed"; exit 1; }; done
sqlite3 $DATA/forecast.db ".backup '$BD/forecast.db'" || echo "(forecast.db backup skipped)"
echo "$BD" > "$MARK"; sha256sum $BD/* $BD/www/* 2>/dev/null
echo "== 3. install"
TMP=$(mktemp -d)
echo '' | base64 -d > $TMP/hf.py
echo '' | base64 -d > $TMP/forecast.html
echo '' | base64 -d > $TMP/embed.js
ok=1
[ "$(h $TMP/hf.py)" = "$NEW" ] || { echo "ABORT: hourly_forecast.py payload hash mismatch"; ok=0; }
[ "$(h $TMP/forecast.html)" = "$NEW_HTML" ] || { echo "ABORT: forecast.html payload hash mismatch"; ok=0; }
[ "$(h $TMP/embed.js)" = "$NEW_JS" ] || { echo "ABORT: embed payload hash mismatch"; ok=0; }
[ $ok = 1 ] && { $ROOT/venv/bin/python -m py_compile "$TMP/hf.py" || { echo "ABORT: does not compile"; ok=0; }; }
[ $ok = 1 ] || { rm -rf "$TMP"; echo "nothing changed"; exit 1; }
cp "$TMP/hf.py" "$F.new-milestones" && mv "$F.new-milestones" "$F"
sudo cp "$TMP/forecast.html" "$WWW/forecast.html"
sudo cp "$TMP/embed.js" "$WWW/celestial_forecast_embed.js"
sudo sed -i 's#celestial_forecast_embed\.js?v=[0-9]*"></script><!-- HOURLY FORECAST v1 -->#celestial_forecast_embed.js?v=5"></script><!-- HOURLY FORECAST v1 -->#' "$WWW/dashboard.html"
rm -rf "$TMP"
if [ "$(h $F)" != "$NEW" ] || [ "$(h $WWW/forecast.html)" != "$NEW_HTML" ] || [ "$(h $WWW/celestial_forecast_embed.js)" != "$NEW_JS" ] \
   || ! grep -q 'celestial_forecast_embed\.js?v=5"' "$WWW/dashboard.html"; then
  echo "== AUTO ROLLBACK (files not as expected after install)"; restore "$BD"; exit 1
fi
echo "installed hourly_forecast.py ${NEW:0:12}, forecast.html ${NEW_HTML:0:12}, embed ${NEW_JS:0:12}, tag v=5"
echo "== 4. restart + health"
sudo systemctl restart kadima
if ! health; then echo "== AUTO ROLLBACK"; restore "$BD"; exit 1; fi
sqlite3 -readonly $DATA/forecast.db ".schema hourly_forecast_revisions" | grep -q trigger_k \
  && echo "revisions table ok" || echo "revisions table not yet created (appears at the first forecast tick)"
free -m | head -2
echo "DONE: release ${NEW:0:12} live. Hard-refresh Celestial (Ctrl+Shift+R): Gamma Blast above Trade Audit,"
echo "no blank space under the forecast. Backup in $BD. Rollback: bash $0 --rollback"
